from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from django_celery_beat.models import PeriodicTask, CrontabSchedule
import json

class ScheduledTaskUpdateView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def patch(self, request, task_id):
        # Validate that the task belongs to the user's organization namespace
        org_prefix = f"org_{request.user.organization_id}_"
        try:
            task = PeriodicTask.objects.get(pk=task_id, name__startswith=org_prefix)
        except PeriodicTask.DoesNotExist:
            return Response({'error': 'Task not found'}, status=status.HTTP_404_NOT_FOUND)

        if 'crontab' in request.data:
            cron_data = request.data['crontab']
            schedule, _ = CrontabSchedule.objects.get_or_create(
                minute=cron_data.get('minute', '*'),
                hour=cron_data.get('hour', '*'),
                day_of_week=cron_data.get('day_of_week', '*'),
                day_of_month=cron_data.get('day_of_month', '*'),
                month_of_year=cron_data.get('month_of_year', '*')
            )
            task.crontab = schedule

        if 'enabled' in request.data:
            task.enabled = bool(request.data['enabled'])

        task.save()
        return Response({'status': 'updated', 'task_name': task.name, 'enabled': task.enabled})
